use localbrain_core::backend::{
    auto_work::{self, PreviewOptions, PreviewSupervisor},
    db, references, Config, Result,
};
use serde_json::Value;
use std::{fs, os::unix::fs::PermissionsExt};
#[test]
fn pure_reconstruction_preserves_complete_frozen_claims_spans_and_corrections() {
    let cases: Value = serde_json::from_str(PURE).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let value = auto_work::reconstruction::reconstruct(
            &case["data"],
            case["corrections"].as_array().unwrap(),
            case["include"].as_bool().unwrap(),
        )
        .unwrap();
        assert_eq!(value, case["expected"], "case {index}");
    }
}
struct Local;
impl PreviewSupervisor for Local {
    fn supervise(&self, operation: &str, args: &Value) -> Result<Value> {
        auto_work::run_preview_operation(operation, args)
    }
}
#[test]
fn explicit_sample_preparation_and_complete_preview_match_frozen_python() {
    let temporary = tempfile::tempdir().unwrap();
    let root = fs::canonicalize(temporary.path()).unwrap();
    let config = Config::for_data_dir(root.join("data"));
    db::initialize(&config).unwrap();
    let connection = db::connect(&config).unwrap();
    connection.execute_batch(SQL).unwrap();
    let at = chrono::DateTime::parse_from_rfc3339("2026-11-18T00:00:00Z")
        .unwrap()
        .with_timezone(&chrono::Utc);
    let prepared = auto_work::reconstruction::prepare_current(
        &config.database_path,
        "2026-11-18T00:00:00+00:00",
        "localbrain.auto-work-preview.v1",
        "2026-11-25T00:00:00+00:00",
    )
    .unwrap();
    assert_eq!(
        references::hash_payload(&prepared),
        PREPARED,
        "prepared: {prepared}"
    );
    auto_work::prepare_preview_with_supervisor(&config, Some(at), &Local).unwrap();
    let cases: Value = serde_json::from_str(PREVIEW).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let value = &case["options"];
        let mut options = PreviewOptions::default();
        if let Some(page) = value["page"].as_str() {
            options.page = page.into();
        }
        options.flow = value["flow"].as_str().map(str::to_owned);
        if let Some(view) = value["view"].as_str() {
            options.view = view.into();
        }
        if let Some(page) = value["evidence_page"].as_str() {
            options.evidence_page = page.into();
        }
        let result = auto_work::preview_page(&config, &options, Some(at));
        assert_eq!(
            references::hash_payload(&result),
            case["hash"],
            "preview {index}: {result}"
        );
    }
    let target = config.cache_dir.join("auto-work-preview/current.json");
    assert_eq!(
        fs::metadata(&target).unwrap().permissions().mode() & 0o777,
        0o600
    );
    assert_eq!(fs::read_dir(target.parent().unwrap()).unwrap().count(), 2);
}
